'use strict';
const $=id=>document.getElementById(id), E=WordLinks, dictionary=window.WORD_DICTIONARY;
function read(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}}
function save(key,value){try{localStorage.setItem(key,JSON.stringify(value))}catch{$('message').textContent='Storage is unavailable. Keep this page open to retain progress.'}}
function dateKey(){const d=new Date;return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
let today=dateKey(),dailyIndex=Math.floor(Date.UTC(...today.split('-').map((x,i)=>Number(x)-(i===1?1:0)))/86400000), index=dailyIndex,practice=false,words=[],selected=null,dir='h',won=false,step=0,helpReturn=null,fits=[],fitIndex=0,anchor=null,anchorIndex=null;
const bests=read('wl-bests',{}),history=read('wl-results',{});
const tutorials=[
['Connect the two green words.','Type a word in the box. We’ll show where it fits on the board. Press “Place word” to add it. Keep linking until the green words are connected.','BLOOM|STONE'],
['Type first. Preview second.','Click a letter on the board, then type your word. If your word repeats that letter, tap the exact occurrence below the word box. The highlighted board square stays fixed.','OCEAN'],
['Your move, your position.','Prefer to place it yourself? Open “Choose a position yourself”, tap the starting square, then choose across or down.','→|↓'],
['Cross at a matching letter.','Each word shares one letter with one existing word. Your last word may cross both separate chains to connect them. Words need a blank square beside them.','LINK'],
['Each word adds points.','A word costs 10 points plus its number of letters. DOG costs 13 points. HOUSE costs 15. The two green words are free.','10 + 5'],
['Connect them for less.','Your goal is the lowest score. Once the green words are connected, replay to find a shorter route. Your best score is saved on this device.','Less is more.']];
function key(){return practice?`practice-${index%72}`:today}
function persist(){save('wl-progress',{today,index,practice,words:words.slice(2),won})}
function init(restore=false){const p=E.puzzle(index);words=p.seeds;won=false;selected=null;anchor=null;anchorIndex=null;fits=[];fitIndex=0;$('word').value='';if(restore){const old=read('wl-progress',null);if(old?.today===today&&Number.isInteger(old.index)&&typeof old.practice==='boolean'&&Array.isArray(old.words)){index=old.index;practice=old.practice;words=E.puzzle(index).seeds;for(const w of old.words){if(!w||typeof w.text!=='string')break;const result=E.validate(words,w,dictionary);if(!result.valid||won)break;words.push({text:w.text,r:w.r,c:w.c,dir:w.dir});won=result.winning}}}render();persist()}
function candidate(){return{text:$('word').value.trim().toUpperCase(),r:selected?.r,c:selected?.c,dir}}
function findFits(text){
 if(!/^[A-Z]{2,15}$/.test(text)||!dictionary.has(text))return [];
 const options=[],seen=new Set;
 for(const p of E.board(words).values())if(!anchor||(p.r===anchor.r&&p.c===anchor.c))for(let i=0;i<text.length;i++)if(text[i]===p.letter)for(const direction of [dir]){
  const w={text,r:p.r-(direction==='v'?i:0),c:p.c-(direction==='h'?i:0),dir:direction};const id=`${w.r},${w.c},${w.dir}`;
  if(!seen.has(id)){seen.add(id);const result=E.validate(words,w,dictionary);if(result.valid)options.push({...w,winning:result.winning})}
 }
 return options.sort((a,b)=>Number(b.winning)-Number(a.winning));
}
function chooseFit(i){fitIndex=(i+fits.length)%fits.length;const w=fits[fitIndex];selected={r:w.r,c:w.c};dir=w.dir;if(anchor)anchorIndex=dir==='h'?anchor.c-w.c:anchor.r-w.r;}
function anchorPreview(){
 const text=$('word').value.trim().toUpperCase();
 if(!anchor||anchorIndex===null||text[anchorIndex]!==anchor.letter){selected=null;return}
 selected={r:anchor.r-(dir==='v'?anchorIndex:0),c:anchor.c-(dir==='h'?anchorIndex:0)};
}
function wordChanged(){
 const text=$('word').value.trim().toUpperCase();fits=won?[]:findFits(text);fitIndex=0;
 if(anchor){
  if(anchorIndex!==null&&text[anchorIndex]===anchor.letter){anchorPreview()}
  else if(fits.length)chooseFit(0);
  else{anchorIndex=text.indexOf(anchor.letter);if(anchorIndex<0)anchorIndex=null;anchorPreview()}
 }else if(fits.length)chooseFit(0);else selected=null;
 render();
}
function selectSquare(r,c){
 if(won)return;
 const hit=E.board(words).get(r*15+c);
 if(hit){anchor={r,c,letter:hit.letter};anchorIndex=null;dir=words[hit.ids[0]].dir==='h'?'v':'h';wordChanged()}
 else{anchor=null;anchorIndex=null;fits=findFits($('word').value.trim().toUpperCase());selected={r,c};$('manual').open=true;render()}
 if(!$('word').value)$('word').focus({preventScroll:true});
}
function renderAnchor(){
 const text=$('word').value.trim().toUpperCase();$('anchor-panel').hidden=!anchor;
 $('crossing-letters').replaceChildren();
 if(!anchor)return;
 $('anchor-label').textContent=`Cross ${anchor.letter} at row ${anchor.r+1}, column ${anchor.c+1}`;
 $('crossing-help').textContent=text.includes(anchor.letter)?'Choose which letter in your word crosses the highlighted square:':`Type a word containing ${anchor.letter}, or click a different board letter.`;
 Array.from(text).forEach((letter,i)=>{const button=document.createElement('button');button.className='crossing-letter';button.textContent=letter;button.disabled=letter!==anchor.letter;button.setAttribute('aria-label',`Use letter ${i+1}, ${letter}, as the crossing`);button.setAttribute('aria-pressed',i===anchorIndex);button.title=`Letter ${i+1}`;button.onclick=()=>{anchorIndex=i;anchorPreview();render()};$('crossing-letters').append(button)});
}
function leaveTutorial(){if($('tutorial').open)$('tutorial').close();save('wl-tutorial',true);$('word').focus();}
function score(){return words.slice(2).reduce((n,w)=>n+10+w.text.length,0)}
function render(){renderAnchor();const b=E.board(words),w=candidate(),result=selected&&w.text?E.validate(words,w,dictionary):null,preview=selected?E.cells(w):[],pmap=new Map(preview.filter(p=>p.r>=0&&p.r<15&&p.c>=0&&p.c<15).map(p=>[p.r*15+p.c,p]));$('grid').replaceChildren();for(let r=0;r<15;r++)for(let c=0;c<15;c++){const pos=r*15+c,existing=b.get(pos),p=pmap.get(pos),button=document.createElement('button');button.className='cell'+(existing?(existing.seed?' seed':' placed'):'')+(p?(result?.valid?' preview-valid':' preview-invalid'):'')+(selected?.r===r&&selected?.c===c?' selected':'')+(anchor?.r===r&&anchor?.c===c?' anchor':'');button.textContent=p?.letter||existing?.letter||'';button.setAttribute('role','gridcell');button.setAttribute('aria-selected',anchor?.r===r&&anchor?.c===c?'true':'false');button.setAttribute('aria-label',`Row ${r+1}, column ${c+1}${existing?', '+existing.letter:''}${existing?.seed?', starting word':''}`);button.tabIndex=selected?(selected.r===r&&selected.c===c?0:-1):(r===0&&c===0?0:-1);button.onclick=()=>selectSquare(r,c);button.onkeydown=e=>{if(/^[a-z]$/i.test(e.key)&&!e.ctrlKey&&!e.metaKey&&!e.altKey){e.preventDefault();$('word').value=($('word').value+e.key).slice(0,15);$('word').focus({preventScroll:true});wordChanged();return}const delta={ArrowUp:[-1,0],ArrowDown:[1,0],ArrowLeft:[0,-1],ArrowRight:[0,1]}[e.key];if(delta){e.preventDefault();const nr=Math.max(0,Math.min(14,r+delta[0])),nc=Math.max(0,Math.min(14,c+delta[1]));$('grid').children[nr*15+nc].focus({preventScroll:true})}};$('grid').append(button)}$('score').innerHTML=`${score()}<span>points</span>`;$('words').textContent=words.length-2;$('moves').textContent=words.length-2;$('best').textContent=bests[key()]??'—';$('horizontal').setAttribute('aria-pressed',dir==='h');$('vertical').setAttribute('aria-pressed',dir==='v');$('selection').textContent=selected?`Starts at row ${selected.r+1}, column ${selected.c+1} · ${dir==='h'?'across':'down'}`:'Tap the square where your word starts.';$('message').textContent=won?'Connected! Replay to find a more efficient route.':result?.reason||(anchor?(!w.text?`Type a word containing ${anchor.letter}.`:!w.text.includes(anchor.letter)?`Your word must include the selected ${anchor.letter}. Choose another word or board letter.`:'Choose a matching letter in your word.'):w.text?(w.text.length<2?'Keep typing — use at least 2 letters.':!dictionary.has(w.text)?'That word is not in our word list. Try another.':`No ${dir==='h'?'horizontal':'vertical'} position is available. Try ${dir==='h'?'Vertical':'Horizontal'} or another word.`):'Click a board letter, then type a word to cross it.');$('message').className=result&&!result.valid?'error':'';$('place').disabled=won||!result?.valid;$('place').innerHTML=result?.valid?`3. Place ${w.text} <span>+${result.cost} points</span>`:'3. Place word <span>↗</span>';$('goal').textContent=`Connect ${words[0].text} to ${words[1].text}.`;$('first-link').hidden=words.length>2||won;$('fit-count').textContent=fits.length?`2. ${anchor?'At selected letter · ':''}${fits.findIndex(f=>f.r===w.r&&f.c===w.c&&f.dir===w.dir)>=0?`Position ${fits.findIndex(f=>f.r===w.r&&f.c===w.c&&f.dir===w.dir)+1} of ${fits.length}`:'Manual position'}`:'2. Preview a position';$('previous-fit').disabled=$('next-fit').disabled=fits.length<2;$('word').disabled=won;$('entry-help').textContent=won?'Puzzle complete! Press Replay or New puzzle to play again.':'Click the exact board letter you want to cross — even when letters repeat.';$('daily-return').hidden=!practice;$('puzzle-label').textContent=practice?'Practice Word Links':"Daily challenge";$('puzzle-number').textContent=`NO. ${String(index%72+1).padStart(3,'0')}`;$('date').textContent=new Date().toLocaleDateString('en-US',{weekday:'long',month:'long',day:'numeric',year:'numeric'}).toUpperCase()}
function place(){if(won)return{ok:false,reason:'Puzzle is complete.'};const w=candidate(),result=E.validate(words,w,dictionary);if(!result.valid)return{ok:false,reason:result.reason};words.push(w);won=result.winning;selected=null;anchor=null;anchorIndex=null;fits=[];fitIndex=0;$('word').value='';if(won){bests[key()]=Math.min(bests[key()]??Infinity,score());save('wl-bests',bests);if(!practice){history[today]={score:score(),words:words.length-2};save('wl-results',history)}}persist();render();if(won)victory();else $('word').focus();return{ok:true,score:score(),complete:won}}
function victory(){$('performance').textContent=score()<=45?'Excellent link. Every letter earned its place.':score()<=65?'Beautifully connected. Can you find a shorter route?':'Connection made. A fresh route could cost you less.';$('final-score').textContent=score()+' points';$('final-stats').textContent=`${words.length-2} words · ${words.length-2} moves · Best: ${bests[key()]} points`;$('share-status').textContent='';$('victory').showModal()}
function reset(newPuzzle){if(words.length>2&&!won&&!confirm('Start over? Your current unfinished links will be cleared.'))return;if($('victory').open)$('victory').close();if(newPuzzle){index++;practice=true}init()}
function showTutorial(){helpReturn=document.activeElement;step=0;drawTutorial();$('tutorial').showModal()}
function drawTutorial(){const t=tutorials[step];$('step-label').textContent=`HOW TO PLAY · ${step+1} OF 6`;$('step-title').textContent=t[0];$('step-copy').textContent=t[1];$('back').disabled=step===0;$('next').textContent=step===5?'Play Word Links':'Next →';$('dots').innerHTML=tutorials.map((_,i)=>`<i class="${i===step?'active':''}"></i>`).join('');$('tutorial-art').innerHTML=step===0?t[2].split('|').map(x=>`<div>${[...x].map(l=>`<span class="tile">${l}</span>`).join('')}</div>`).join('<span class="connector">⋯</span>'):step===2?`<span class="points">→ &nbsp; ↓</span>`:step===1?[...'OCEAN'].map(l=>`<span class="tile">${l}</span>`).join(''):step===3?[...'LINK'].map(l=>`<span class="tile">${l}</span>`).join(''):`<span class="points">${t[2].replace('|',' &nbsp; ')}</span>`;if(step===0){$('tutorial-art').style.flexDirection='column'}else $('tutorial-art').style.flexDirection='row'}
$('next').onclick=()=>{if(step<5){step++;drawTutorial()}else{leaveTutorial()}};$('back').onclick=()=>{if(step){step--;drawTutorial()}};$('help').onclick=showTutorial;$('close-help').onclick=leaveTutorial;$('start-now').onclick=leaveTutorial;$('tutorial').addEventListener('cancel',()=>save('wl-tutorial',true));$('word').oninput=wordChanged;$('word').onkeydown=e=>{if(e.key==='Enter'&&!$('place').disabled)place()};$('horizontal').onclick=()=>{dir='h';wordChanged()};$('vertical').onclick=()=>{dir='v';wordChanged()};$('clear-anchor').onclick=()=>{anchor=null;anchorIndex=null;wordChanged()};$('previous-fit').onclick=()=>{if(fits.length){chooseFit(fitIndex-1);render()}};$('next-fit').onclick=()=>{if(fits.length){chooseFit(fitIndex+1);render()}};$('first-link').onclick=()=>{anchor=null;anchorIndex=null;const example=E.puzzle(index).solution[0];dir=example.dir;$('word').value=example.text;fits=findFits(example.text);const i=fits.findIndex(f=>f.r===example.r&&f.c===example.c&&f.dir===example.dir);if(i>=0)chooseFit(i);render();$('message').textContent='This is a preview, not a move yet. Press Place OCEAN to add your first link.';};$('place').onclick=place;$('replay').onclick=()=>reset(false);$('new').onclick=()=>reset(true);$('win-replay').onclick=()=>reset(false);$('win-new').onclick=()=>reset(true);$('view-board').onclick=()=>$('victory').close();$('share').onclick=async()=>{const text=`Bostonian Times Word Links\n${practice?'Practice puzzle '+(index%72+1):today}\nScore: ${score()}\nWords: ${words.length-2}\nMoves: ${words.length-2}\n🟩${'▫️'.repeat(Math.min(words.length-2,10))}🟩`;try{await navigator.clipboard.writeText(text);$('share-status').textContent='Result copied. Your words stay a secret.'}catch{$('share-status').textContent='Copy your result below:';const area=document.createElement('textarea');area.value=text;area.style.width='100%';$('share-status').append(area);area.select()}};
$('daily-return').onclick=()=>{if(words.length>2&&!won&&!confirm('Return to today’s puzzle and clear these practice links?'))return;index=dailyIndex;practice=false;init()};
init(true);if(!read('wl-tutorial',false))showTutorial();
window.addEventListener('focus',()=>{if(dateKey()!==today){today=dateKey();dailyIndex=Math.floor(Date.UTC(...today.split('-').map((x,i)=>Number(x)-(i===1?1:0)))/86400000);index=dailyIndex;practice=false;if($('victory').open)$('victory').close();init()}});
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'get_word_links_board',description:'Read the current Word Links puzzle, placed words and score.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({words:words.map(w=>({...w})),score:score(),complete:won})})).catch(()=>{});Promise.resolve(document.modelContext.registerTool({name:'place_word_link',description:'Place a word on the current board using zero-based row and column. Invalid placements leave the board unchanged.',inputSchema:{type:'object',properties:{word:{type:'string'},row:{type:'integer',minimum:0,maximum:14},column:{type:'integer',minimum:0,maximum:14},direction:{type:'string',enum:['h','v']}},required:['word','row','column','direction'],additionalProperties:false},execute:input=>{if(typeof input.word!=='string'||!Number.isInteger(input.row)||!Number.isInteger(input.column)||!['h','v'].includes(input.direction))return{ok:false,reason:'Invalid word placement input.'};const proposed={text:input.word.toUpperCase(),r:input.row,c:input.column,dir:input.direction};const result=E.validate(words,proposed,dictionary);if(!result.valid||won)return{ok:false,reason:won?'Puzzle is complete.':result.reason};anchor=null;anchorIndex=null;selected={r:input.row,c:input.column};dir=input.direction;$('word').value=proposed.text;return place()}})).catch(()=>{})}catch{}}
